content:
{
  "book_code": "2ES",
  "verses": [
    {
      "text_ar": "قسّمتُ أراضٍ مثمرةً بينكم. وطردتُ أمامكم الكنعانيين والفرزيين والفلسطينيين. ماذا أعمل أيضاً لكم؟ يقول الرب.",
      "chapter": 1,
      "verse": 21
    },
    {
      "text_ar": "يقول الرب القدير: \"لما كنتم في البرية، عند النهر المرّ، إذ كنتم عطاشى وتجدّفون على اسمي،",
      "chapter": 1,
      "verse": 22
    },
    {
      "text_ar": "لم أعطِكم ناراً بدلاً من تجديفكم، بل طرحتُ شجرةً في الماء، فصيرتُ النهر حلواً.",
      "chapter": 1,
      "verse": 23
    },
    {
      "text_ar": "ماذا أفعلك يا يعقوب؟ أما أنت يا يهوذا فما أردتَ أن تطيعني. سألتفتُ إلى أمم أخرى، وأعطي اسمي لهم لكي يحفظوا فرائضي.",
      "chapter": 1,
      "verse": 24
    },
    {
      "text_ar": "بما أنكم تركتموني، فسأترككم أنا أيضاً. ومتى طلبتُم مني أن أرحمكم، فلن أرحمكم.",
      "chapter": 1,
      "verse": 25
    },
    {
      "text_ar": "كلما دعوتموني، فلن أسمع لكم، لأنكم نجّستم أيديكم بالدم، وأقدامكم سريعة لإرتكاب القتل.",
      "chapter": 1,
      "verse": 26
    },
    {
      "text_ar": "ليس كأنكم تركتموني، بل تركتم أنفسكم\"، يقول الرب.",
      "chapter": 1,
      "verse": 27
    },
    {
      "text_ar": "يقول الرب القدير: \"أما طلبتُ إليكم كأب أبناءه، وكأم بناتها، وكمرضعة أطفالها الصغار،",
      "chapter": 1,
      "verse": 28
    },
    {
      "text_ar": "أن تكونوا شعبي وأكون إلهكم، وأن تكونوا أولادي وأكون أباكم؟",
      "chapter": 1,
      "verse": 29
    },
    {
      "text_ar": "لقد جمعتُكم معاً، كما تجمع الدجاجة فراخها تحت أجنحتها. ولكن الآن، ماذا أعمل بكم؟ سأطردكم من أمامي.",
      "chapter": 1,
      "verse": 30
    },
    {
      "text_ar": "عندما تقدمون لي ذبائح محرقة، سأحرف وجهي عنكم، لأني رفضتُ أعيادكم المقدسة، ورؤوس شهوركم، وختان جسدكم.",
      "chapter": 1,
      "verse": 31
    },
    {
      "text_ar": "أرسلتُ إليكم عبيدي الأنبياء، الذين أخذتموهم وقتلتموهم، ومزقتم أجسامهم قطعاً، والتي ستطلب دماءهم منكم\"، يقول الرب.",
      "chapter": 1,
      "verse": 32
    },
    {
      "text_ar": "يقول الرب القدير: \"بيتكُم خراب. سأطردكم كما تسفي الريح القش.",
      "chapter": 1,
      "verse": 33
    },
    {
      "text_ar": "لن يثمر أولادكم، لأنهم أهملوا وصيتي لكم، وعملوا الشر قدامي.",
      "chapter": 1,
      "verse": 34
    },
    {
      "text_ar": "سأعطي بيوتكم لشعب يأتي، وهو لم يسمع بي بعد ولكنه يؤمن بي. والذين لم أُظهر لهم آيات سيصنعون ما أمرتُ به.",
      "chapter": 1,
      "verse": 35
    },
    {
      "text_ar": "لم يروا أنبياء، ولكنه سيذكرون حالتهم السابقة.",
      "chapter": 1,
      "verse": 36
    },
    {
      "text_ar": "أشهد بامتنان الشعب الآتي، الذي يفرح صغاره بابتهاج. مع أنهم لا يرونني بعيون الجسد، إلا أنهم بالروح سيؤمنون بما أقوله.\"",
      "chapter": 1,
      "verse": 37
    },
    {
      "text_ar": "والآن أيها الأب، انظر بمجد، وأبصر الشعب الآتي من الشرق:",
      "chapter": 1,
      "verse": 38
    },
    {
      "text_ar": "الذين سأعطيهم قادةً: إبراهيم وإسحاق ويعقوب، هوشع وعاموس وميخا، يوئيل وعوبديا يونان،",
      "chapter": 1,
      "verse": 39
    },
    {
      "text_ar": "ناحوم وحبقوق وصفنيا وحجاي زكريا وملاخي، الذي يُدعى أيضاً رسول الرب.",
      "chapter": 1,
      "verse": 40
    }
  ]
}
